const html = $input.first().json.data;

// Try standard JSON-LD first
const match = html.match(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/);

if (match) {
  const job = JSON.parse(match[1]);
  return [{ json: {
    title: job.title,
    company: job.hiringOrganization?.name,
    location: job.jobLocation,
    salary: job.baseSalary?.value ?? job.baseSalary?.minValue ?? null
  }}];
}

// LinkedIn fallback
const rawTitle = html.match(/<title>(.*?)<\/title>/)?.[1] ?? '';
// LinkedIn title format: "Company hiring Job Title in Location | LinkedIn"
const titleMatch = rawTitle.match(/hiring (.+?) in (.+?)(?:\s*\||\s*$)/);

const title = titleMatch?.[1]?.trim() ?? rawTitle.replace(' | LinkedIn', '').trim();
const location = titleMatch?.[2]?.trim() ?? null;
const company = 
  html.match(/"companyName":"(.*?)"/)?.[1] ??
  html.match(/"name":"(.*?)","url":"https:\/\/www\.linkedin\.com\/company/)?.[1] ??
  html.match(/,"topCard".*?"name":"(.*?)"/)?.[1] ??
  rawTitle.match(/^(.*?)\s+hiring/)?.[1]?.trim() ?? // fallback: grab from title tag
  null;
const salary = html.match(/"formattedSalaryRange":"(.*?)"/)?.[1] ?? null;

return [{ json: { title, company, location, salary }}];
